from taf.collectors.core.templates.dynamic_class_creation import Creating
from taf.collectors.core.factories.named_factory import NamedComponentFactory, Factory
from .collector import L2Trace3GCollector, BrowserServer, CellThroughputCollector

import logging

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class BrowserServerFactory(Factory):
    """
    Factory to create BrowserServer tool instance
    """
    _optional_parameters = {"bts_host", "bts_port", "enable_extra_log"}
    _product_class = BrowserServer


class BrowserServerFactoryBase(Creating("file_getter", "LocalFileGetter"),
                               NamedComponentFactory):
    """
    Factory base for `CellThroughputCollectorFactory` and `L2Trace3gCollectorFactory`.
    """
    _mandatory_parameters = {"cell_id", "tool"}
    _optional_parameters = {"target_file_name", "as_zip"}


class CellThroughputCollectorFactory(BrowserServerFactoryBase):
    """
    Factory to create a CellThroughputCollectorFactory.
    """
    _product_class = CellThroughputCollector


class L2Trace3gCollectorFactory(BrowserServerFactoryBase):
    """
    Factory to create a L2trace3GCollectorFactory.
    """
    _product_class = L2Trace3GCollector
